{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MapleMonk.zouk_ebo_available_inventory_score` AS WITH disp AS ( SELECT Store_Code, ANY_VALUE(Store_Name) AS store_name, ANY_VALUE(SAFE_CAST(Min_Disp_Cap AS FLOAT64)) AS min_disp, ANY_VALUE(SAFE_CAST(Max_Store_Cap AS FLOAT64)) AS max_cap, ANY_VALUE(SAFE_CAST(TAT AS FLOAT64)) AS tat FROM `zouk-wh.MapleMonk.zouk_EBO_Display_TAT` WHERE Store_Code IS NOT NULL GROUP BY Store_Code ), loc AS ( SELECT SAFE_CAST(Location_ID AS INT64) AS loc, Store_Code FROM `zouk-wh.MapleMonk.Zouk_Offline_EBO_Store_Master` WHERE Location_ID IS NOT NULL ), past AS ( SELECT l.Store_Code, SUM(s.QUANTITY) / 30.0 AS past_drr FROM `zouk-wh.MapleMonk.zouk_SHOPIFY_FACT_ITEMS` s JOIN loc l ON l.loc = SAFE_CAST(s.location_id AS INT64) WHERE s.Grouped_Channel = \'EBO Stores\' AND IFNULL(s.order_status,\'\') != \'Cancelled\' AND s.LINE_ITEM_SALES > 0 AND UPPER(TRIM(s.SKU_CODE)) NOT IN (\'ZSHOP-M\',\'ZSHOP-L\',\'ZSHOP-S\') AND DATE(s.order_timestamp) >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) GROUP BY 1 ), fut AS ( SELECT l.Store_Code, SUM(s.QUANTITY) / 30.0 AS future_drr FROM `zouk-wh.MapleMonk.zouk_SHOPIFY_FACT_ITEMS` s JOIN loc l ON l.loc = SAFE_CAST(s.location_id AS INT64) WHERE s.Grouped_Channel = \'EBO Stores\' AND IFNULL(s.order_status,\'\') != \'Cancelled\' AND s.LINE_ITEM_SALES > 0 AND UPPER(TRIM(s.SKU_CODE)) NOT IN (\'ZSHOP-M\',\'ZSHOP-L\',\'ZSHOP-S\') AND DATE(s.order_timestamp) BETWEEN DATE \'2026-05-01\' AND DATE \'2026-05-31\' GROUP BY 1 ), drr AS ( SELECT d.Store_Code, p.past_drr, f.future_drr, CASE WHEN p.past_drr IS NULL AND f.future_drr IS NULL THEN NULL ELSE LEAST(IFNULL(p.past_drr, f.future_drr), IFNULL(f.future_drr, p.past_drr)) END AS drr FROM disp d LEFT JOIN past p ON p.Store_Code = d.Store_Code LEFT JOIN fut f ON f.Store_Code = d.Store_Code ), inv AS ( SELECT l.Store_Code, DATE(f.DATA_FETCH_DATE) AS date, SUM(f.Available_Inventory) AS total_inv FROM `zouk-wh.MapleMonk.ZOUK_STORE_INVENTORY_FACT_ITEMS` f JOIN loc l ON l.loc = SAFE_CAST(f.location_id AS INT64) WHERE DATE(f.DATA_FETCH_DATE) >= DATE \'2026-09-01\' AND UPPER(IFNULL(f.COMMONSKU,\'\')) NOT IN (\'ZSHOP-M\',\'ZSHOP-L\',\'ZSHOP-S\') GROUP BY 1, 2 ), tgt AS ( SELECT Store_Code, Date AS date, ANY_VALUE(SAFE_CAST(Target AS FLOAT64)) AS day_target FROM `zouk-wh.MapleMonk.zouk_store_target_vs_achievement` WHERE Store_Code IS NOT NULL GROUP BY Store_Code, Date ) SELECT inv.date, inv.Store_Code AS store_code, d.store_name, CASE WHEN EXTRACT(DAYOFWEEK FROM inv.date) IN (1,7) THEN \'weekend\' ELSE \'weekday\' END AS day_type, inv.total_inv, d.min_disp, d.max_cap, d.tat, ROUND(dr.past_drr, 4) AS past_drr, ROUND(dr.future_drr, 4) AS future_drr, ROUND(dr.drr, 4) AS drr, ROUND(LEAST(d.min_disp + IFNULL(dr.drr,0) * (7 + d.tat), d.max_cap), 1) AS ideal_3i, inv.total_inv - d.min_disp AS additional_stock, CASE WHEN inv.total_inv >= LEAST(d.min_disp + IFNULL(dr.drr,0) * (7 + d.tat), d.max_cap) THEN 1 ELSE 0 END AS available, t.day_target, (CASE WHEN inv.total_inv >= LEAST(d.min_disp + IFNULL(dr.drr,0) * (7 + d.tat), d.max_cap) THEN 1 ELSE 0 END) * t.day_target AS weighted_target FROM inv JOIN disp d ON d.Store_Code = inv.Store_Code LEFT JOIN drr dr ON dr.Store_Code = inv.Store_Code LEFT JOIN tgt t ON t.Store_Code = inv.Store_Code AND t.date = inv.date ORDER BY store_code, date",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            